        static ArchiveStationState GraphState=>session.State.stations[8];
        static IEnumerator GraphBook(Peer peer){yield return Move(peer,session.stations[8],ArchiveTopicStation.BookPosition+Vector3.back*1.7f);yield return Send(peer,8,ArchiveAction.Start);}
        static IEnumerator GraphClaim(Peer peer){var q=session.Question(8);yield return Move(peer,session.stations[8],ArchiveGraphTraversal.Vertex(q,ArchiveGraphTraversal.StartIndex(q)));yield return Send(peer,8,ArchiveAction.RetryRoute);}
        static IEnumerator GraphWalkTo(Peer peer,Vector3 target){var st=session.stations[8];var from=st.transform.InverseTransformPoint(session.ActorPlayer(peer.Actor).transform.position);from.y=0;int steps=Mathf.CeilToInt(Vector3.Distance(from,target)/.30f);for(int i=1;i<=steps;i++){yield return Move(peer,st,Vector3.Lerp(from,target,i/(float)steps));yield return .035f;}yield return .2f;}
