        static IEnumerator GraphFlow(Peer a,string room){bool oldHunting=session.hunting.enabled;session.hunting.enabled=false;session.Initialize(314159);var st=session.stations[8];Status="T9 runner ownership and exact penalty";yield return GraphBook(a);var state=GraphState;var q=session.Question(8);Check(state.timerRunning&&Mathf.Approximately(state.timerLimit,session.graphTimeLimitSeconds*session.PacingMultiplier)&&state.timerActor==a.Actor&&state.routeActor==0&&session.ActiveTopic==8,"Guest Book starts the shared graph clock without claiming a runner");double deadline=state.timerDeadline;yield return GraphClaim(a);yield return Send(a,8,ArchiveAction.Submit,spoof:true);Check(session.State.mistakes.Count==1&&session.State.mistakes[0].actor==a.Actor&&state.routeActor==a.Actor&&Math.Abs(state.timerDeadline-(deadline-10))<.000001,"Early Confirm charges authenticated runner once and deducts exactly ten seconds");int revision=session.State.revision;Packet(a,lastCommand);yield return .25f;Check(session.State.mistakes.Count==1&&session.State.revision==revision,"Replayed Confirm cannot charge another mistake");q=session.Question(8);var answer=ArchiveTopicChecks.Solution(q).route;var end=ArchiveGraphTraversal.Vertex(q,answer[1]);var start=ArchiveGraphTraversal.Vertex(q,answer[0]);yield return GraphWalkTo(a,Vector3.Lerp(start,end,.58f));Check(state.route.Count==1&&state.routeEdge>=0&&state.routeCrossedMiddle&&!state.routeAtVertex,"Remote movement checkpoints an unfinished connecting edge past its midpoint");
            Status="T9 late join and connecting-edge host handoff";var b=Connect("Archive guest B QA");yield return Wait(()=>b.client.State==ClientState.ConnectedToMasterServer,"T9 second peer connected");b.client.OpJoinRoom(new EnterRoomParams{RoomName=room});yield return Wait(()=>b.client.InRoom&&b.state!=null&&b.state.stations[8].routeEdge>=0,"T9 late peer receives current edge");Spawn(b,Position(st,start));yield return Wait(()=>session.ActorPlayer(b.Actor)!=null,"T9 second replica ready");Check(b.state.stations[8].route.SequenceEqual(state.route)&&b.state.stations[8].routeActor==a.Actor&&b.state.stations[8].routeCrossedMiddle&&Math.Abs(b.state.stations[8].timerDeadline-state.timerDeadline)<.000001,"Late join restores route runner, midpoint checkpoint and exact shared deadline");revision=session.State.revision;Packet(b,Command(b,8,ArchiveAction.RetryRoute),true);yield return .25f;Check(state.routeActor==a.Actor&&session.State.revision==revision,"A teammate cannot steal a live runner even while standing on START");Packet(b,Command(b,8,ArchiveAction.Submit),true);yield return .25f;Check(session.State.mistakes.Count==1&&state.round==0,"A teammate cannot confirm another actor's physical route");var fake=JsonUtility.FromJson<ArchiveTeamState>(JsonUtility.ToJson(session.State));fake.revision+=1000;fake.stations[8].phase=2;b.client.OpRaiseEvent(ArchiveTopicSession.SnapshotEvent,new object[]{ArchiveTopicSession.Channel,JsonUtility.ToJson(fake)},new RaiseEventOptions{Receivers=ReceiverGroup.All},SendOptions.SendReliable);yield return .25f;Check(session.ActiveTopic==8&&a.state.stations[8].phase==1,"Guest cannot forge a completed graph snapshot");int pending=state.routeEdge;deadline=state.timerDeadline;PhotonNetwork.SetMasterClient(PhotonNetwork.CurrentRoom.GetPlayer(a.Actor));yield return Wait(()=>!PhotonNetwork.IsMasterClient&&a.client.CurrentRoom.MasterClientId==a.Actor,"T9 master handoff");a.client.CurrentRoom.SetMasterClient(a.client.CurrentRoom.GetPlayer(PhotonNetwork.LocalPlayer.ActorNumber));yield return Wait(()=>PhotonNetwork.IsMasterClient,"T9 Editor regains authority");yield return .2f;state=GraphState;Check(state.routeActor==a.Actor&&state.routeEdge==pending&&state.routeCrossedMiddle&&state.continuous&&Math.Abs(state.timerDeadline-deadline)<.000001,"Handoff preserves the unfinished bridge transaction and clock");yield return GraphWalkTo(a,end);Check(state.continuous&&state.route.SequenceEqual(answer.Take(2))&&state.routeAtVertex,"The pending edge finishes after the Master handoff");foreach(int vertex in answer.Skip(2)){yield return GraphWalkTo(a,ArchiveGraphTraversal.Vertex(q,vertex));Check(state.continuous&&state.routeAtVertex&&state.route.Last()==vertex,"Remote runner continues the full updated route after handoff");}Check(state.route.SequenceEqual(answer),"The complete source route finishes after the Master handoff");yield return Send(a,8,ArchiveAction.Submit);Check(state.round==1&&state.phase==0&&!state.timerRunning&&b.state.stations[8].round==1,"Walked edge completes for every peer and pauses the same remaining clock");yield return BlockedBook(b,0,"Unfinished T9 prevents starting a different topic");
            Status="T9 shared degree and timeout recovery";yield return GraphBook(b);q=session.Question(8);int degree=q.graph.Degree(q.graph.degreeVertex);yield return Send(b,8,ArchiveAction.Select,degree);Check(a.state.stations[8].selection==degree&&state.selection==degree,"Degree selection is shared team work without a route owner");state.timerDeadline=ArchiveTopicSession.TimerClock-.01;yield return Wait(()=>state.timerExpired&&a.state.stations[8].timerExpired,"T9 degree timeout replicates",8);Check(state.round==1&&state.selection==degree&&session.State.mistakes.Count==2&&session.State.mistakes.Last().actor==0&&session.State.mistakes.Last().reason=="timeout","Timeout retains solved edge and selected degree and records one shared team mistake");yield return GraphBook(b);yield return Send(b,8,ArchiveAction.Submit);Check(state.round==2&&state.phase==0,"Teammate retry completes preserved degree work");
            Status="T9 runner capture and restart";yield return GraphBook(b);yield return GraphClaim(b);var capture=session.hunting.GetSnapshot();capture.state=(int)KhezuHuntState.Caught;capture.target=capture.caught=b.Actor;capture.captureSerial++;capture.huntSerial++;capture.capturePosition=session.ActorPlayer(b.Actor).transform.position;capture.captureAnchorValid=true;capture.captureStartedAt=KhezuHuntingController.EncounterClock-3;capture.encounterPhase=4;capture.awake=true;capture.pending=false;capture.animation="Idle";capture.animationSpeed=1;session.hunting.ApplySnapshot(capture,true);yield return .3f;Check(!session.CanAct(b.Actor)&&session.CanAct(a.Actor)&&state.routeActor==0&&!state.continuous,"Capture releases the unavailable runner while leaving other players free");revision=session.State.revision;Packet(b,Command(b,8,ArchiveAction.RetryRoute));yield return .25f;Check(state.routeActor==0&&session.State.revision==revision,"Captured guest cannot reclaim graph traversal");session.hunting.Request(KhezuCommand.Sleep);yield return .2f;yield return GraphWalkAnswer(a);yield return Send(a,8,ArchiveAction.Submit);Check(state.round==3&&state.phase==0,"Another teammate can restart and solve the simple path after capture");
            Status="T9 directed route and departed-runner recovery";yield return GraphBook(a);yield return GraphClaim(a);int former=a.Actor;var history=session.State.mistakes[0].actor;a.client.Disconnect();yield return Wait(()=>PhotonNetwork.CurrentRoom.GetPlayer(former)==null,"T9 runner departure");yield return .25f;Check(state.routeActor==0&&!state.continuous&&session.ActorName(former)=="Archive guest A QA"&&history==former&&session.State.mistakes.Count==2,"Runner departure frees START without losing mistake identity or charging a new mistake");yield return GraphWalkAnswer(b);yield return Send(b,8,ArchiveAction.Submit);Check(state.round==4&&b.state.stations[8].round==4,"Directed path through actual remote movement completes for the room");yield return GraphBook(b);yield return GraphWalkAnswer(b);Check(state.route.Count>=4&&state.route.First()==state.route.Last(),"Remote cycle closes at its source after distinct intermediate vertices");yield return Send(b,8,ArchiveAction.Submit);Check(state.phase==2&&state.round==5&&!state.timerRunning&&session.ActiveTopic==-1&&b.state.stations[8].phase==2,"All five shared graph challenges finish and release the next topic");Check(session.State.stations.Where(s=>s.topic!=8).All(s=>s.round==0&&s.timerAttempt==0),"T9 transport flow leaves the other nine topics unchanged");session.hunting.enabled=oldHunting;session.hunting.Request(KhezuCommand.Sleep);Status="Completed T9 transport checks";
        }
